@CrossOrigin
@RestController
@RequestMapping("/LotQuery")
public class LotQueryRestController extends BaseSpringRestController {
	
	public LotQueryRestController( LotService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Lot using a UUID
     * @param		UUID lotId
     * @return		Lot
     */    
    @GetMapping("/load")
    public Lot load( @RequestParam(required=true) UUID lotId ) {
    	Lot entity = null;

    	try {  
    		entity = service.getLot( new LotFetchOneSummary( lotId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Lot using Id " + lotId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Lot business objects
     * @return		Set<Lot>
     */
    @GetMapping("/")
    public List<Lot> loadAll() {                
    	List<Lot> lotList = null;
        
    	try {
            // load the Lot
            lotList = service.getAllLot();
            
            if ( lotList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Lots" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Lots ", exc );
        	return null;
        }

        return lotList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Lot lot = null;
    protected LotService service = null;
    private static final Logger LOGGER = Logger.getLogger(LotQueryRestController.class.getName());
    
}
